```yaml
name: Workflow Approval
on:
  pull_request_target:
    types: [labeled, synchronize]
    branches:
      - main
      - release-**
permissions:
  contents: read
jobs:
  approve-workflow:
    if: github.event_name == 'pull_request_target'
    runs-on: ubuntu-latest
    permissions:
      actions: write
    steps:
      - name: Check if contributor is returning or has ok-to-test label
        id: check-contributor
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo, number } = context.issue;
            const prNumber = context.payload.pull_request.number;
            const labels = context.payload.pull_request.labels.map(label => label.name);

            // Check if ok-to-test label is present
            const hasOkToTest = labels.includes('ok-to-test');

            // Get PR history for this user
            const query = `
              query($owner: String!, $repo: String!, $author: String!) {
                repository(owner: $owner, name: $repo) {
                  pullRequests(first: 100, states: OPENED, orderBy: {field: CREATED_AT, direction: DESC}) {
                    nodes {
                      author {
                        login
                      }
                      number
                    }
                  }
                }
              }
            `;

            const result = await github.graphql(query, {
              owner: owner,
              repo: repo,
              author: context.payload.pull_request.user.login
            });

            let isReturningContributor = false;
            if (result.repository.pullRequests.nodes) {
              const userPRs = result.repository.pullRequests.nodes.filter(pr => pr.author.login === context.payload.pull_request.user.login);
              isReturningContributor = userPRs.length <= 1;
            }

            // Set outputs
            core.setOutput('is_returning', isReturningContributor);
            core.setOutput('has_ok_to_test', hasOkToTest);

            // If either condition is met, approve the workflow
            if (isReturningContributor || hasOkToTest) {
              const workflows = await github.rest.actions.listWorkflowRunsForRepo({
                owner: owner,
                repo: repo,
                event: 'pull_request',
                status: 'pending'
              });

              for (const workflow of workflows.data.workflow_runs) {
                if (workflow.head_branch === context.payload.pull_request.base.ref && 
                    workflow.pull_requests.some(pr => pr.number === prNumber)) {
                  try {
                    await github.rest.actions.approveWorkflowRun({
                      owner: owner,
                      repo: repo,
                      run_id: workflow.id
                    });
                    console.log(`Approved workflow run ${workflow.id}`);
                  } catch (error) {
                    console.error(`Failed to approve workflow run ${workflow.id}:`, error);
                  }
                }
              }
            }
